// spec: specs/stale-chunk-reload.md (1.3) · кейс: .qa/tests/stale-chunk-reload/STALE-CHUNK-03
// seed: tests/seed.spec.ts (гость) · прод, только просмотр; Chromium (десктоп и Pixel 7).
// 15 с без перезагрузок — требование «за время»: ожидание события навигации с таймаутом, не фиксированная пауза.
import { test, expect } from '@playwright/test';
import {
  DEVICES, ERROR_TEXT, LOAD,
  breakCalculatorChunk, clickCalculatorLink, openHome, prepare, trackDocumentNavigations,
} from './stale-chunk.helpers';

test.use({ serviceWorkers: 'block' });

test.describe('устаревший чанк после деплоя — автозагрузка новой версии', () => {
  for (const device of DEVICES) {
    test(`чанк недоступен постоянно → 1 перезагрузка, «${ERROR_TEXT}» с «טען מחדש», 15 с без перезагрузок #4f5e3a ${device} @prod-safe`, async ({ page, context, browserName }) => {
      test.skip(browserName !== 'chromium', 'только Chromium (по сценарию тикета)');
      test.setTimeout(90_000);
      await prepare(context);
      const chunk = await breakCalculatorChunk(page, '404-always');
      await openHome(page);

      const docs = trackDocumentNavigations(page);
      await clickCalculatorLink(page);

      await expect(page.getByText(ERROR_TEXT).first(), 'экран ошибки после попытки перезагрузки').toBeVisible(LOAD);
      await expect(page.getByRole('button', { name: 'טען מחדש' }), 'кнопка «טען מחדש»').toBeVisible();
      expect(chunk.hits, 'чанк запрашивался до и после перезагрузки').toBeGreaterThanOrEqual(2);
      expect(docs, 'ровно одна перезагрузка').toHaveLength(1);

      const extra = await page
        .waitForRequest((r) => r.isNavigationRequest() && r.frame() === page.mainFrame(), { timeout: 15_000 })
        .then((r) => r.url())
        .catch(() => null);
      expect(extra, 'за 15 с новых перезагрузок нет').toBeNull();
      expect(docs).toHaveLength(1);
      await expect(page.getByText(ERROR_TEXT).first()).toBeVisible();
    });
  }
});
